        val propre = titre.trim()
        if (propre.isEmpty()) return
        _taches.update { it + Tache(prochainId++, propre) }
    }

    fun basculer(id: Long) = _taches.update { it.basculer(id) }

    fun supprimer(id: Long) = _taches.update { liste -> liste.filterNot { it.id == id } }
