fun formater(millis: Long): String {
    val minutes = millis / 60_000
    val secondes = millis / 1_000 % 60
    val centiemes = millis / 10 % 100
    return "%02d:%02d.%02d".format(minutes, secondes, centiemes)
}

class ChronoViewModel(private val horloge: () -> Long) : ViewModel() {
    private val _ecoule = MutableStateFlow(0L)
    val ecoule: StateFlow<Long> = _ecoule.asStateFlow()
    private var tache: Job? = null

    fun demarrer() {
        if (tache?.isActive == true) return
        val origine = horloge() - _ecoule.value
        tache = viewModelScope.launch {
            while (true) {
                _ecoule.value = horloge() - origine
                delay(30)
            }
        }
    }

    fun pause() {
        tache?.cancel()
    }

    fun remettreAZero() {
        pause()
        _ecoule.value = 0
    }
}

val fabriqueChrono = object : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T =
        ChronoViewModel(SystemClock::elapsedRealtime) as T
}

