data class Fichier(val nom: String, val taille: Long)

fun lister(dossier: File): List<Fichier> =
    dossier.listFiles().orEmpty()
        .filter { it.isFile }
        .map { Fichier(it.name, it.length()) }
        .sortedBy { it.nom.lowercase() }

fun fichierSur(dossier: File, nom: String): File? {
    val cible = File(dossier, nom).canonicalFile
    val autorise = cible.path.startsWith(dossier.canonicalPath + File.separator)
    return if (autorise) cible else null
}

fun importer(context: Context, uri: Uri, nom: String): Boolean {
    val cible = fichierSur(context.filesDir, nom) ?: return false
    val entree = context.contentResolver.openInputStream(uri) ?: return false
    entree.use { source -> cible.outputStream().use { source.copyTo(it) } }
    return true
}

