private const val ALIAS_SESSION = "cle_session"

fun cleSession(): SecretKey {
    val magasin = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    (magasin.getKey(ALIAS_SESSION, null) as? SecretKey)?.let { return it }
    val generateur = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
    generateur.init(
        KeyGenParameterSpec.Builder(
            ALIAS_SESSION,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .build()
    )
    return generateur.generateKey()
}

fun enregistrer(fichier: File, jeton: String) {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, cleSession())
    fichier.writeBytes(cipher.iv + cipher.doFinal(jeton.toByteArray()))
}

class Renouvellement(
    private val renouveler: () -> String?,
) : Authenticator {
    override fun authenticate(route: Route?, response: okhttp3.Response): Request? {
        if (response.priorResponse != null) return null
        val jeton = renouveler() ?: return null
        return response.request.newBuilder()
