fun creerCanal(context: Context) {
    val canal = NotificationChannel(
        CANAL_RAPPELS,
        "Rappels",
        NotificationManager.IMPORTANCE_DEFAULT,
    )
    context.getSystemService(NotificationManager::class.java)
        .createNotificationChannel(canal)
}

class ActionReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val id = intent.getIntExtra("id", 0)
        context.getSystemService(NotificationManager::class.java).cancel(id)
    }
}

fun notification(context: Context, id: Int, texte: String): Notification {
    val action = Intent(context, ActionReceiver::class.java).putExtra("id", id)
    val terminer = PendingIntent.getBroadcast(
        context,
        id,
        action,
        PendingIntent.FLAG_IMMUTABLE,
    )
    return NotificationCompat.Builder(context, CANAL_RAPPELS)
        .setSmallIcon(android.R.drawable.ic_popup_reminder)
        .setContentTitle("Rappel")
        .setContentText(texte)
        .addAction(0, "Terminer", terminer)
        .setAutoCancel(true)
        .build()
}

class RappelWorker(
    context: Context,
    parametres: WorkerParameters,
) : CoroutineWorker(context, parametres) {
    override suspend fun doWork(): Result {
        val texte = inputData.getString("texte") ?: return Result.failure()
        val gestionnaire = applicationContext.getSystemService(NotificationManager::class.java)
        if (gestionnaire.areNotificationsEnabled()) {
            gestionnaire.notify(id.hashCode(), notification(applicationContext, id.hashCode(), texte))
        }
        return Result.success()
    }
}

fun planifier(context: Context, texte: String, minutes: Long) {
    val requete = OneTimeWorkRequestBuilder<RappelWorker>()
        .setInitialDelay(minutes, TimeUnit.MINUTES)
        .setInputData(workDataOf("texte" to texte))
        .build()
    WorkManager.getInstance(context).enqueue(requete)
}

