fun minutesAvant(heureCible: Int, minuteCible: Int, heure: Int, minute: Int): Int {
    val cible = heureCible * 60 + minuteCible
    val maintenant = heure * 60 + minute
    return if (cible > maintenant) cible - maintenant else cible - maintenant + 24 * 60
}

fun main() {
    println(minutesAvant(9, 0, 8, 30))
    println(minutesAvant(9, 0, 9, 0))
    println(minutesAvant(9, 0, 23, 0))
}

fun versionCode(majeur: Int, mineur: Int, correctif: Int): Int {
    require(mineur in 0..99 && correctif in 0..99)
    return majeur * 10_000 + mineur * 100 + correctif
}

fun main() {
    println(versionCode(1, 0, 0))
    println(versionCode(1, 0, 1) > versionCode(1, 0, 0))
    println(versionCode(1, 10, 0) > versionCode(1, 9, 9))
}

