data class Article(val id: Long, val titre: String, val lu: Boolean)

interface ArticlesDepot {
    fun articles(): Flow<List<Article>>
    suspend fun actualiser()
}

class ArticlesNonLus(private val depot: ArticlesDepot) {
    operator fun invoke(): Flow<List<Article>> =
        depot.articles().map { liste -> liste.filterNot { it.lu } }
}

data class ArticlesUiState(
    val articles: List<Article> = emptyList(),
    val chargement: Boolean = false,
    val erreur: String? = null,
)

class ArticlesViewModel(
    nonLus: ArticlesNonLus,
    private val depot: ArticlesDepot,
) : ViewModel() {
    private val etatReseau = MutableStateFlow(ArticlesUiState())

    val uiState: StateFlow<ArticlesUiState> =
        combine(nonLus(), etatReseau) { articles, etat -> etat.copy(articles = articles) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), ArticlesUiState())

    fun actualiser() {
        etatReseau.update { it.copy(chargement = true, erreur = null) }
        viewModelScope.launch {
            try {
                depot.actualiser()
                etatReseau.update { it.copy(chargement = false) }
            } catch (e: IOException) {
                etatReseau.update { it.copy(chargement = false, erreur = "Connexion impossible") }
            }
        }
    }
}

