import 'package:flutter/material.dart';

enum Disposition { compacte, large }

Disposition dispositionPour(double largeur) =>
    largeur < 700 ? Disposition.compacte : Disposition.large;

class Accueil extends StatelessWidget {
  const Accueil({super.key});

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, contraintes) =>
          switch (dispositionPour(contraintes.maxWidth)) {
            Disposition.compacte => const Text('Navigation en bas'),
            Disposition.large => const Text('Navigation latérale'),
          },
    );
  }
}

