fun plusRecente(a: String, b: String): Boolean {
    val x = a.split(".").map { it.toInt() }
    val y = b.split(".").map { it.toInt() }
    for (i in x.indices) {
        if (x[i] != y[i]) return x[i] > y[i]
    }
    return false
}

fun main() {
    println(plusRecente("1.10.0", "1.9.9"))
    println(plusRecente("1.2.0", "1.2.0"))
    println("1.10.0" > "1.9.9")
}
